void test_FR_011_01(void)
{
    ride_events_t state;
    bool led_on = false;
    const ride_sample_t baseline = {0.0F, 0.0F, 0.0F, 100U};
    const ride_sample_t below_threshold = {0.0F, 0.0F, 0.299F, 110U};
    const ride_sample_t at_threshold = {0.0F, 0.0F, 0.30F, 120U};

    ride_events_init(&state, false);
    ride_events_sample(&state, &baseline);
    ride_events_sample(&state, &below_threshold);
    TEST_ASSERT_EQUAL_INT(RIDE_NONE, ride_events_update(&state, 110U, &led_on));

    ride_events_sample(&state, &at_threshold);
    TEST_ASSERT_EQUAL_INT(RIDE_BUMP, ride_events_update(&state, 120U, &led_on));
}

